import{_ as a,o,c as r,a2 as e}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"🧪 03 · 测试（含 AI 评测）","description":"","frontmatter":{},"headers":[],"relativePath":"07-开发岗-前后端与全栈/03-测试.md","filePath":"07-开发岗-前后端与全栈/03-测试.md","lastUpdated":1786806808000}'),l={name:"07-开发岗-前后端与全栈/03-测试.md"};function s(i,t,n,c,p,d){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="🧪-03-·-测试-含-ai-评测" tabindex="-1">🧪 03 · 测试（含 AI 评测） <a class="header-anchor" href="#🧪-03-·-测试-含-ai-评测" aria-label="Permalink to &quot;🧪 03 · 测试（含 AI 评测）&quot;">​</a></h1><blockquote><p>传统测试保「功能正确」；AI 测试还要保「输出质量稳定」。这是 AI 应用质量保障的难点。</p></blockquote><hr><h2 id="一、传统测试" tabindex="-1">一、传统测试 <a class="header-anchor" href="#一、传统测试" aria-label="Permalink to &quot;一、传统测试&quot;">​</a></h2><ul><li><strong>单元测试</strong>：函数/模块正确性（pytest/JUnit/Go test）。</li><li><strong>接口测试</strong>：API 契约、边界、异常。</li><li><strong>性能测试</strong>：压测（QPS、延迟、P99）、容量规划。</li><li><strong>E2E/UI 测试</strong>：关键流程自动化。</li></ul><h2 id="二、ai-应用测试的特殊性" tabindex="-1">二、AI 应用测试的特殊性 <a class="header-anchor" href="#二、ai-应用测试的特殊性" aria-label="Permalink to &quot;二、AI 应用测试的特殊性&quot;">​</a></h2><ul><li><strong>非确定性</strong>：同输入模型输出可能不同 → 不能简单 assert 相等，用「评测指标 + 容忍窗口」。</li><li><strong>质量回归</strong>：模型/ Prompt 一改，质量可能悄悄下降 → 需<strong>评测集 + 自动化打分</strong>（RAGAS / LLM-as-Judge）。</li><li><strong>幻觉/安全测试</strong>：构造对抗 case，验证不胡说、不越权。</li><li><strong>RAG 测试</strong>：检索召回率、生成忠实度分开测。</li></ul><h2 id="三、治理" tabindex="-1">三、治理 <a class="header-anchor" href="#三、治理" aria-label="Permalink to &quot;三、治理&quot;">​</a></h2><ul><li>固化「黄金测试集」，每次发布跑回归。</li><li>灰度发布 + 在线 AB + 监控告警。</li><li>Prompt/模型版本化，可回滚。</li></ul><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：AI 输出不确定，怎么写测试？</strong></p><blockquote><p>不测「逐字相等」，测「属性」：用评测集+自动打分（如 LLM-as-Judge）检查正确性/相关性/格式；对关键逻辑用确定性 mock 模型。</p></blockquote><p><strong>Q2：怎么防 Prompt 改坏效果？</strong></p><blockquote><p>维护质量评测集，CI 中跑自动化评测；关键指标设阈值，未达标阻断发布；做 Prompt 版本管理与灰度。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-运维与DevOps">04-运维与DevOps</a></p>',16)])])}const g=a(l,[["render",s]]);export{u as __pageData,g as default};
